import type { Snippet } from "svelte";
import type { Attachment } from "svelte/attachments";
import type {
  HTMLAttributes,
  HTMLButtonAttributes,
  HTMLOptionAttributes,
  HTMLSelectAttributes,
  HTMLTableAttributes,
  HTMLTdAttributes,
  HTMLThAttributes,
} from "svelte/elements";

export type CalendarMode = "multiple" | "range" | "single";
export type CaptionLayout = "dropdown" | "dropdown-months" | "dropdown-years" | "label";

export interface DateRange {
  from: Date | undefined;
  to?: Date | undefined;
}

export type CalendarSelection = Date | Date[] | DateRange | undefined;

export type DateMatcher =
  | boolean
  | Date
  | Date[]
  | ((date: Date) => boolean)
  | { after: Date; before?: never }
  | { before: Date; after?: never }
  | { after: Date; before: Date }
  | { dayOfWeek: number | number[] }
  | { from: Date | undefined; to?: Date | undefined };

export interface CalendarLocale {
  [key: string]: unknown;
  code?: string;
  options?: {
    firstWeekContainsDate?: 1 | 4;
    weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  };
  localize?: unknown;
}

export interface CalendarClassNames {
  [part: string]: string | undefined;
  button_next?: string;
  button_previous?: string;
  caption_label?: string;
  day?: string;
  day_button?: string;
  dropdown?: string;
  dropdown_root?: string;
  dropdowns?: string;
  hidden?: string;
  month?: string;
  month_caption?: string;
  months?: string;
  nav?: string;
  outside?: string;
  range_end?: string;
  range_middle?: string;
  range_start?: string;
  today?: string;
  week_number?: string;
  weekday?: string;
}

export interface CalendarFormatterOptions {
  firstWeekContainsDate: 1 | 4;
  locale: CalendarLocale;
  localeCode: string;
  numerals: CalendarNumerals;
  timeZone?: string | undefined;
  weekStartsOn: 0 | 1 | 2 | 3 | 4 | 5 | 6;
}

export interface CalendarFormatters {
  formatCaption?: (month: Date, options: CalendarFormatterOptions) => string;
  formatDay?: (date: Date, options: CalendarFormatterOptions) => string;
  /** @deprecated Use `formatCaption`. */
  formatMonthCaption?: (month: Date, options: CalendarFormatterOptions) => string;
  formatMonthDropdown?: (month: Date, options: CalendarFormatterOptions) => string;
  formatWeekNumber?: (weekNumber: number, options: CalendarFormatterOptions) => string;
  formatWeekNumberHeader?: (options: CalendarFormatterOptions) => string;
  formatWeekdayName?: (weekday: Date, options: CalendarFormatterOptions) => string;
  /** @deprecated Use `formatYearDropdown`. */
  formatYearCaption?: (year: Date, options: CalendarFormatterOptions) => string;
  formatYearDropdown?: (year: Date, options: CalendarFormatterOptions) => string;
}

export interface CalendarDayModel {
  date: Date;
  displayMonth: Date;
  outside: boolean;
}

export interface CalendarModifiers {
  [name: string]: boolean;
  disabled: boolean;
  focused: boolean;
  hidden: boolean;
  outside: boolean;
  range_end: boolean;
  range_middle: boolean;
  range_start: boolean;
  selected: boolean;
  today: boolean;
  unavailable: boolean;
}

export interface CalendarDayContext extends CalendarDayModel {
  disabled: boolean;
  hidden: boolean;
  rangeEnd: boolean;
  rangeMiddle: boolean;
  rangeStart: boolean;
  selected: boolean;
  today: boolean;
  unavailable: boolean;
}

export type CalendarDayButtonProps = Omit<HTMLButtonAttributes, "children"> & {
  children: Snippet;
  day: CalendarDayModel;
  modifiers: CalendarModifiers;
};

export interface CalendarDropdownContext {
  "aria-label": string;
  class?: string | undefined;
  disabled: boolean;
  kind: "month" | "year";
  onChange: (value: number) => void;
  options: ReadonlyArray<{ disabled?: boolean; label: string; value: number }>;
  style?: CalendarStyle;
  value: number;
}

export interface CalendarDropdownNavContext {
  children: Snippet;
  class: string | undefined;
  style?: CalendarStyle;
}

export interface CalendarChevronContext {
  class?: string | undefined;
  disabled?: boolean | undefined;
  orientation?: "down" | "left" | "right" | "up";
  size?: number | undefined;
  style?: CalendarStyle;
}

export interface CalendarWeekModel {
  days: readonly CalendarDayModel[];
  weekNumber: number;
}

export interface CalendarWeekNumberContext {
  dates: readonly Date[];
  weekNumber: number;
}

export type CalendarWeekNumberProps = Omit<HTMLThAttributes, "children"> & {
  children: Snippet;
  week: CalendarWeekModel;
};

type CalendarHostProps<Attributes> = Omit<Attributes, "children"> & { children: Snippet };

export interface CalendarMonthModel {
  date: Date;
  weeks: readonly CalendarWeekModel[];
}

export type CalendarCaptionLabelProps = CalendarHostProps<HTMLAttributes<HTMLSpanElement>>;
export type CalendarDayProps = CalendarHostProps<HTMLTdAttributes> & {
  day: CalendarDayModel;
  modifiers: CalendarModifiers;
};
export type CalendarFooterProps = CalendarHostProps<HTMLAttributes<HTMLDivElement>>;
export type CalendarMonthProps = CalendarHostProps<HTMLAttributes<HTMLDivElement>> & {
  calendarMonth: CalendarMonthModel;
  displayIndex: number;
};
export type CalendarMonthCaptionProps = CalendarMonthProps;
export type CalendarMonthGridProps = CalendarHostProps<HTMLTableAttributes>;
export type CalendarMonthsProps = CalendarHostProps<HTMLAttributes<HTMLDivElement>>;
export type CalendarNavProps = CalendarHostProps<HTMLAttributes<HTMLElement>> & {
  nextMonth?: Date | undefined;
  onNextClick?: (event: MouseEvent) => void;
  onPreviousClick?: (event: MouseEvent) => void;
  previousMonth?: Date | undefined;
};
export type CalendarNavigationButtonProps = CalendarHostProps<HTMLButtonAttributes>;
export type CalendarOptionProps = Omit<HTMLOptionAttributes, "children"> & {
  children: Snippet;
  label: string;
};
export type CalendarRootComponentProps = CalendarHostProps<HTMLAttributes<HTMLDivElement>> & {
  rootRef?: Attachment<HTMLDivElement>;
};
export type CalendarSelectProps = CalendarHostProps<HTMLSelectAttributes>;
export type CalendarWeekProps = CalendarHostProps<HTMLAttributes<HTMLTableRowElement>> & {
  week: CalendarWeekModel;
};
export type CalendarWeekdayProps = CalendarHostProps<HTMLThAttributes> & { weekday: Date };
export type CalendarWeekdaysProps = CalendarHostProps<HTMLAttributes<HTMLTableRowElement>>;
export type CalendarWeekNumberHeaderProps = CalendarHostProps<HTMLThAttributes>;
export type CalendarWeeksProps = CalendarHostProps<HTMLAttributes<HTMLTableSectionElement>>;

export interface CalendarComponents {
  CaptionLabel?: Snippet<[CalendarCaptionLabelProps]>;
  Chevron?: Snippet<[CalendarChevronContext]>;
  Day?: Snippet<[CalendarDayProps]>;
  DayButton?: Snippet<[CalendarDayButtonProps]>;
  Dropdown?: Snippet<[CalendarDropdownContext]>;
  DropdownNav?: Snippet<[CalendarDropdownNavContext]>;
  Footer?: Snippet<[CalendarFooterProps]>;
  Month?: Snippet<[CalendarMonthProps]>;
  MonthCaption?: Snippet<[CalendarMonthCaptionProps]>;
  MonthGrid?: Snippet<[CalendarMonthGridProps]>;
  Months?: Snippet<[CalendarMonthsProps]>;
  MonthsDropdown?: Snippet<[CalendarDropdownContext]>;
  Nav?: Snippet<[CalendarNavProps]>;
  NextMonthButton?: Snippet<[CalendarNavigationButtonProps]>;
  Option?: Snippet<[CalendarOptionProps]>;
  PreviousMonthButton?: Snippet<[CalendarNavigationButtonProps]>;
  Root?: Snippet<[CalendarRootComponentProps]>;
  Select?: Snippet<[CalendarSelectProps]>;
  Week?: Snippet<[CalendarWeekProps]>;
  Weekday?: Snippet<[CalendarWeekdayProps]>;
  Weekdays?: Snippet<[CalendarWeekdaysProps]>;
  WeekNumber?: Snippet<[CalendarWeekNumberProps]>;
  WeekNumberHeader?: Snippet<[CalendarWeekNumberHeaderProps]>;
  Weeks?: Snippet<[CalendarWeeksProps]>;
  YearsDropdown?: Snippet<[CalendarDropdownContext]>;
}

export interface CalendarLabels {
  labelDayButton?: (date: Date, modifiers: CalendarModifiers) => string;
  /** @deprecated Use `labelDayButton`. */
  labelDay?: (date: Date, modifiers: CalendarModifiers) => string;
  labelGrid?: (month: Date, options: CalendarFormatterOptions) => string;
  labelGridcell?: (date: Date, modifiers: CalendarModifiers) => string;
  labelMonthDropdown?: (options: CalendarFormatterOptions) => string;
  labelNav?: () => string;
  labelNext?: (month: Date | undefined) => string;
  labelPrevious?: (month: Date | undefined) => string;
  labelWeekday?: (weekday: Date, options: CalendarFormatterOptions) => string;
  labelWeekNumber?: (weekNumber: number) => string;
  labelWeekNumberHeader?: () => string;
  labelYearDropdown?: (options: CalendarFormatterOptions) => string;
}

type CalendarRootProps = Omit<
  HTMLAttributes<HTMLDivElement>,
  "children" | "class" | "hidden" | "onkeydown" | "onselect" | "style"
>;

export type CalendarNumerals =
  | "arab"
  | "arabext"
  | "beng"
  | "deva"
  | "geez"
  | "gujr"
  | "guru"
  | "khmr"
  | "knda"
  | "laoo"
  | "latn"
  | "mlym"
  | "mymr"
  | "orya"
  | "tamldec"
  | "telu"
  | "thai"
  | "tibt";

export type CalendarStyle = HTMLAttributes<HTMLDivElement>["style"];
export type CalendarStyles = Record<string, CalendarStyle | undefined>;

interface CalendarBaseProps extends CalendarRootProps {
  animate?: boolean;
  autoFocus?: boolean;
  broadcastCalendar?: boolean;
  captionLayout?: CaptionLayout;
  class?: string;
  className?: string;
  classNames?: CalendarClassNames;
  components?: CalendarComponents;
  day?: Snippet<[CalendarDayContext]>;
  defaultMonth?: Date;
  disableNavigation?: boolean;
  disabled?: DateMatcher | DateMatcher[];
  endMonth?: Date;
  fixedWeeks?: boolean;
  firstWeekContainsDate?: 1 | 4;
  footer?: Snippet | string;
  formatters?: CalendarFormatters;
  hidden?: DateMatcher | DateMatcher[];
  hideNavigation?: boolean;
  hideWeekdays?: boolean;
  ISOWeek?: boolean;
  labels?: CalendarLabels;
  locale?: CalendarLocale;
  maxDate?: Date;
  minDate?: Date;
  modifiers?: Record<string, DateMatcher | DateMatcher[] | undefined>;
  modifiersClassNames?: Record<string, string>;
  modifiersStyles?: CalendarStyles;
  month?: Date;
  navLayout?: "after" | "around";
  noonSafe?: boolean;
  numerals?: CalendarNumerals;
  numberOfMonths?: number;
  onDayBlur?: (date: Date, modifiers: CalendarModifiers, event: FocusEvent) => void;
  onDayClick?: (date: Date, modifiers: CalendarModifiers, event: MouseEvent) => void;
  onDayFocus?: (date: Date, modifiers: CalendarModifiers, event: FocusEvent) => void;
  onDayKeyDown?: (date: Date, modifiers: CalendarModifiers, event: KeyboardEvent) => void;
  onDayMouseEnter?: (date: Date, modifiers: CalendarModifiers, event: MouseEvent) => void;
  onDayMouseLeave?: (date: Date, modifiers: CalendarModifiers, event: MouseEvent) => void;
  onMonthChange?: (month: Date) => void;
  onNextClick?: (month: Date) => void;
  onPrevClick?: (month: Date) => void;
  pagedNavigation?: boolean;
  ref?: HTMLDivElement | null;
  reverseMonths?: boolean;
  reverseYears?: boolean;
  showOutsideDays?: boolean;
  showWeekNumber?: boolean;
  startMonth?: Date;
  style?: CalendarStyle;
  styles?: CalendarStyles;
  timeZone?: string;
  today?: Date;
  unavailable?: DateMatcher | DateMatcher[];
  weekNumber?: Snippet<[CalendarWeekNumberContext]>;
  weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
}

export type CalendarSelectEvent = KeyboardEvent | MouseEvent;

export interface CalendarSingleProps extends CalendarBaseProps {
  excludeDisabled?: never;
  max?: never;
  min?: never;
  mode?: "single";
  onSelect?: (
    selected: Date | undefined,
    triggerDate: Date,
    modifiers: CalendarModifiers,
    event: CalendarSelectEvent,
  ) => void;
  required?: false | undefined;
  resetOnSelect?: never;
  selected?: Date | undefined;
}

export interface CalendarSingleRequiredProps extends CalendarBaseProps {
  excludeDisabled?: never;
  max?: never;
  min?: never;
  mode?: "single";
  onSelect?: (
    selected: Date,
    triggerDate: Date,
    modifiers: CalendarModifiers,
    event: CalendarSelectEvent,
  ) => void;
  required: true;
  resetOnSelect?: never;
  selected: Date | undefined;
}

export interface CalendarMultipleProps extends CalendarBaseProps {
  excludeDisabled?: never;
  max?: number;
  min?: number;
  mode: "multiple";
  onSelect?: (
    selected: Date[] | undefined,
    triggerDate: Date,
    modifiers: CalendarModifiers,
    event: CalendarSelectEvent,
  ) => void;
  required?: false | undefined;
  resetOnSelect?: never;
  selected?: Date[] | undefined;
}

export interface CalendarMultipleRequiredProps extends CalendarBaseProps {
  excludeDisabled?: never;
  max?: number;
  min?: number;
  mode: "multiple";
  onSelect?: (
    selected: Date[],
    triggerDate: Date,
    modifiers: CalendarModifiers,
    event: CalendarSelectEvent,
  ) => void;
  required: true;
  resetOnSelect?: never;
  selected: Date[] | undefined;
}

export interface CalendarRangeProps extends CalendarBaseProps {
  excludeDisabled?: boolean;
  max?: number;
  min?: number;
  mode: "range";
  onSelect?: (
    selected: DateRange | undefined,
    triggerDate: Date,
    modifiers: CalendarModifiers,
    event: CalendarSelectEvent,
  ) => void;
  required?: false | undefined;
  resetOnSelect?: boolean;
  selected?: DateRange | undefined;
}

export interface CalendarRangeRequiredProps extends CalendarBaseProps {
  excludeDisabled?: boolean;
  max?: number;
  min?: number;
  mode: "range";
  onSelect?: (
    selected: DateRange,
    triggerDate: Date,
    modifiers: CalendarModifiers,
    event: CalendarSelectEvent,
  ) => void;
  required: true;
  resetOnSelect?: boolean;
  selected: DateRange | undefined;
}

export type CalendarProps =
  | CalendarMultipleProps
  | CalendarMultipleRequiredProps
  | CalendarRangeProps
  | CalendarRangeRequiredProps
  | CalendarSingleProps
  | CalendarSingleRequiredProps;

import type { CalendarMode, CalendarSelection, DateMatcher, DateRange } from "./calendar.types.js";

const DAY_MS = 86_400_000;

export interface CalendarDateOptions {
  noonSafe?: boolean;
  timeZone?: string | undefined;
}

function zonedDateParts(
  date: Date,
  timeZone: string,
): { day: number; month: number; year: number } {
  const parts = new Intl.DateTimeFormat("en-US-u-ca-gregory-nu-latn", {
    day: "numeric",
    month: "numeric",
    timeZone,
    year: "numeric",
  }).formatToParts(date);
  const value = (type: Intl.DateTimeFormatPartTypes) =>
    Number(parts.find((part) => part.type === type)?.value);
  return { day: value("day"), month: value("month") - 1, year: value("year") };
}

export function createCalendarDate(
  year: number,
  month: number,
  day: number,
  options: CalendarDateOptions = {},
): Date {
  return new Date(year, month, day, options.noonSafe && options.timeZone ? 12 : 0);
}

export function normalizeCalendarDate(date: Date, options: CalendarDateOptions = {}): Date {
  const parts = options.timeZone
    ? zonedDateParts(date, options.timeZone)
    : { day: date.getDate(), month: date.getMonth(), year: date.getFullYear() };
  return createCalendarDate(parts.year, parts.month, parts.day, options);
}

export function startOfCalendarMonth(date: Date, options: CalendarDateOptions = {}): Date {
  return createCalendarDate(date.getFullYear(), date.getMonth(), 1, options);
}

export function addCalendarDays(
  date: Date,
  amount: number,
  options: CalendarDateOptions = {},
): Date {
  const next = createCalendarDate(date.getFullYear(), date.getMonth(), date.getDate(), options);
  next.setDate(next.getDate() + amount);
  return createCalendarDate(next.getFullYear(), next.getMonth(), next.getDate(), options);
}

export function addCalendarMonths(
  date: Date,
  amount: number,
  options: CalendarDateOptions = {},
): Date {
  const firstOfTarget = createCalendarDate(
    date.getFullYear(),
    date.getMonth() + amount,
    1,
    options,
  );
  const lastOfTarget = createCalendarDate(
    firstOfTarget.getFullYear(),
    firstOfTarget.getMonth() + 1,
    0,
    options,
  );
  return createCalendarDate(
    firstOfTarget.getFullYear(),
    firstOfTarget.getMonth(),
    Math.min(date.getDate(), lastOfTarget.getDate()),
    options,
  );
}

export function differenceInCalendarMonths(left: Date, right: Date): number {
  return left.getFullYear() * 12 + left.getMonth() - (right.getFullYear() * 12 + right.getMonth());
}

export function isSameCalendarDay(left: Date | undefined, right: Date | undefined): boolean {
  return Boolean(
    left &&
      right &&
      left.getFullYear() === right.getFullYear() &&
      left.getMonth() === right.getMonth() &&
      left.getDate() === right.getDate(),
  );
}

export function compareCalendarDays(left: Date, right: Date): number {
  return (
    Date.UTC(left.getFullYear(), left.getMonth(), left.getDate()) -
    Date.UTC(right.getFullYear(), right.getMonth(), right.getDate())
  );
}

export function differenceInCalendarDays(left: Date, right: Date): number {
  return Math.round(compareCalendarDays(left, right) / DAY_MS);
}

export function isDateMatched(
  date: Date,
  matcher: DateMatcher | DateMatcher[] | undefined,
  options: CalendarDateOptions = {},
): boolean {
  if (matcher === undefined || matcher === false) return false;
  if (matcher === true) return true;
  if (Array.isArray(matcher)) {
    if (matcher.length === 0) return false;
    if (matcher.every((entry) => entry instanceof Date)) {
      return matcher.some((entry) =>
        isSameCalendarDay(date, normalizeCalendarDate(entry as Date, options)),
      );
    }
    return matcher.some((entry) => isDateMatched(date, entry, options));
  }
  if (matcher instanceof Date)
    return isSameCalendarDay(date, normalizeCalendarDate(matcher, options));
  if (typeof matcher === "function") return matcher(date);
  if ("dayOfWeek" in matcher) {
    const days = Array.isArray(matcher.dayOfWeek) ? matcher.dayOfWeek : [matcher.dayOfWeek];
    return days.includes(date.getDay());
  }
  if ("from" in matcher) {
    if (matcher.from && !matcher.to) {
      return compareCalendarDays(date, normalizeCalendarDate(matcher.from, options)) >= 0;
    }
    if (!matcher.from && matcher.to) {
      return compareCalendarDays(date, normalizeCalendarDate(matcher.to, options)) <= 0;
    }
    if (!matcher.from || !matcher.to) return false;
    return (
      compareCalendarDays(date, normalizeCalendarDate(matcher.from, options)) >= 0 &&
      compareCalendarDays(date, normalizeCalendarDate(matcher.to, options)) <= 0
    );
  }
  if ("before" in matcher && "after" in matcher && matcher.before && matcher.after) {
    const after = normalizeCalendarDate(matcher.after, options);
    const before = normalizeCalendarDate(matcher.before, options);
    const isAfterBoundary = compareCalendarDays(date, after) > 0;
    const isBeforeBoundary = compareCalendarDays(date, before) < 0;
    return compareCalendarDays(before, after) > 0
      ? isAfterBoundary && isBeforeBoundary
      : isBeforeBoundary || isAfterBoundary;
  }
  if ("before" in matcher && matcher.before) {
    return compareCalendarDays(date, normalizeCalendarDate(matcher.before, options)) < 0;
  }
  if ("after" in matcher && matcher.after) {
    return compareCalendarDays(date, normalizeCalendarDate(matcher.after, options)) > 0;
  }
  return false;
}

export interface CalendarDayModelData {
  date: Date;
  outside: boolean;
}

export interface CalendarMonthModel {
  value: Date;
  weeks: Array<Array<CalendarDayModelData>>;
}

export function buildCalendarMonth(
  month: Date,
  options: CalendarDateOptions & {
    broadcastCalendar?: boolean;
    fixedWeeks?: boolean;
    weekStartsOn?: number;
  } = {},
): CalendarMonthModel {
  const value = startOfCalendarMonth(month, options);
  const weekStartsOn = (((options.weekStartsOn ?? 0) % 7) + 7) % 7;
  const firstOffset = (value.getDay() - weekStartsOn + 7) % 7;
  const firstDate = addCalendarDays(value, -firstOffset, options);
  const lastOfMonth = createCalendarDate(value.getFullYear(), value.getMonth() + 1, 0, options);
  const naturalCells = firstOffset + lastOfMonth.getDate();
  let cellCount = options.fixedWeeks ? 42 : Math.ceil(naturalCells / 7) * 7;
  if (options.broadcastCalendar) {
    const fifthWeekEnd = addCalendarDays(firstDate, 34, options);
    const broadcastWeeks = fifthWeekEnd.getMonth() === value.getMonth() ? 5 : 4;
    cellCount = options.fixedWeeks ? 35 : broadcastWeeks * 7;
  }
  const weeks: CalendarMonthModel["weeks"] = [];

  for (let offset = 0; offset < cellCount; offset += 7) {
    const week: CalendarMonthModel["weeks"][number] = [];
    for (let day = 0; day < 7; day += 1) {
      const date = addCalendarDays(firstDate, offset + day, options);
      week.push({ date, outside: date.getMonth() !== value.getMonth() });
    }
    weeks.push(week);
  }
  return { value, weeks };
}

function addToRange(
  date: Date,
  initialRange: DateRange | undefined,
  options: { max?: number; min?: number; required?: boolean },
): DateRange | undefined {
  const { from, to } = initialRange ?? {};
  const min = options.min ?? 0;
  const max = options.max ?? 0;
  let range: DateRange | undefined;

  if (!from && !to) range = min > 0 ? { from: date, to: undefined } : { from: date, to: date };
  else if (from && !to) {
    if (isSameCalendarDay(from, date)) {
      if (min === 0) range = { from, to: date };
      else range = options.required ? { from, to: undefined } : undefined;
    } else if (compareCalendarDays(date, from) < 0) range = { from: date, to: from };
    else range = { from, to: date };
  } else if (from && to) {
    if (isSameCalendarDay(from, date) && isSameCalendarDay(to, date)) {
      range = options.required ? { from, to } : undefined;
    } else if (isSameCalendarDay(from, date)) {
      range = min > 0 ? { from, to: undefined } : { from, to: date };
    } else if (isSameCalendarDay(to, date)) {
      range = min > 0 ? { from: date, to: undefined } : { from: date, to: date };
    } else if (compareCalendarDays(date, from) < 0) range = { from: date, to };
    else range = { from, to: date };
  }

  if (range?.from && range.to) {
    const diff = differenceInCalendarDays(range.to, range.from);
    if (max > 0 && diff > max) range = { from: date, to: undefined };
    else if (min > 1 && diff < min) range = { from: date, to: undefined };
  }
  return range;
}

export function resolveCanonicalSelection(
  mode: CalendarMode,
  date: Date,
  current: CalendarSelection,
  options: {
    max?: number;
    min?: number;
    required?: boolean;
    resetOnSelect?: boolean;
  } = {},
): CalendarSelection {
  const nextDate = date;
  if (mode === "single") {
    const selected = current instanceof Date ? current : undefined;
    if (isSameCalendarDay(selected, nextDate)) return options.required ? selected : undefined;
    return nextDate;
  }

  if (mode === "multiple") {
    const selected = Array.isArray(current) ? current : [];
    const index = selected.findIndex((entry) => isSameCalendarDay(entry, nextDate));
    if (index >= 0) {
      if (options.required && selected.length === 1) return selected;
      if (options.min !== undefined && selected.length === options.min) return selected;
      return selected.filter((_, itemIndex) => itemIndex !== index);
    }
    if (options.max !== undefined && selected.length === options.max) return [nextDate];
    return [...selected, nextDate];
  }

  const currentRange =
    current && !(current instanceof Date) && !Array.isArray(current) ? current : undefined;
  const range = currentRange;
  const isFullRange = Boolean(range?.from && range.to);
  const isClickingSingleDayRange = Boolean(
    range?.from &&
      range.to &&
      isSameCalendarDay(range.from, range.to) &&
      isSameCalendarDay(nextDate, range.from),
  );
  if (options.resetOnSelect && (isFullRange || !range?.from)) {
    if (!options.required && isClickingSingleDayRange) return undefined;
    return { from: nextDate, to: undefined };
  }
  return addToRange(nextDate, range, options);
}

export function resolveSelection(
  mode: CalendarMode,
  date: Date,
  current: CalendarSelection,
  options: {
    max?: number;
    min?: number;
    noonSafe?: boolean;
    required?: boolean;
    resetOnSelect?: boolean;
    timeZone?: string | undefined;
  } = {},
): CalendarSelection {
  return resolveCanonicalSelection(mode, normalizeCalendarDate(date, options), current, options);
}

export function isSelectedDate(
  mode: CalendarMode,
  date: Date,
  selected: CalendarSelection,
): boolean {
  if (mode === "single") return selected instanceof Date && isSameCalendarDay(date, selected);
  if (mode === "multiple") {
    return Array.isArray(selected) && selected.some((entry) => isSameCalendarDay(entry, date));
  }
  if (!selected || selected instanceof Date || Array.isArray(selected)) return false;
  if (!selected.from) return false;
  if (!selected.to) return isSameCalendarDay(date, selected.from);
  return (
    compareCalendarDays(date, selected.from) >= 0 && compareCalendarDays(date, selected.to) <= 0
  );
}

export function getRangeFlags(
  date: Date,
  selected: CalendarSelection,
): { rangeEnd: boolean; rangeMiddle: boolean; rangeStart: boolean } {
  if (!selected || selected instanceof Date || Array.isArray(selected) || !selected.from) {
    return { rangeEnd: false, rangeMiddle: false, rangeStart: false };
  }
  const rangeStart = Boolean(selected.to && isSameCalendarDay(date, selected.from));
  const rangeEnd = Boolean(selected.to && isSameCalendarDay(date, selected.to));
  const rangeMiddle = Boolean(
    selected.to &&
      compareCalendarDays(date, selected.from) > 0 &&
      compareCalendarDays(date, selected.to) < 0,
  );
  return { rangeEnd, rangeMiddle, rangeStart };
}

export function getIsoWeekNumber(date: Date): number {
  const utc = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const day = utc.getUTCDay() || 7;
  utc.setUTCDate(utc.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(utc.getUTCFullYear(), 0, 1));
  return Math.ceil(((utc.getTime() - yearStart.getTime()) / DAY_MS + 1) / 7);
}

export function getCalendarWeekNumber(
  date: Date,
  options: { firstWeekContainsDate?: 1 | 4; weekStartsOn?: number } = {},
): number {
  const weekStartsOn = (((options.weekStartsOn ?? 0) % 7) + 7) % 7;
  const firstWeekContainsDate = options.firstWeekContainsDate ?? 1;
  const startOfWeek = (value: Date): Date => {
    const offset = (value.getDay() - weekStartsOn + 7) % 7;
    return addCalendarDays(value, -offset);
  };
  const weekYearStart = (year: number) => startOfWeek(new Date(year, 0, firstWeekContainsDate));
  let weekYear = date.getFullYear();
  if (compareCalendarDays(date, weekYearStart(weekYear)) < 0) weekYear -= 1;
  else if (compareCalendarDays(date, weekYearStart(weekYear + 1)) >= 0) weekYear += 1;
  return Math.floor(differenceInCalendarDays(date, weekYearStart(weekYear)) / 7) + 1;
}
